// @FIGURE_CODE_BEGIN
var BLUE = '#1a6fae', RED = '#d1271b', GRID = '#cfcfcf', INK = '#111';
var S = { c: -1, m: 1, sol: { kind: 'unique', x: -7/3, y: 2/3 } };

function computeSolution() {
  if (Math.abs(2 * S.m + 1) < 1e-9) {
    if (Math.abs(S.c - 6) < 1e-9) { S.sol = { kind: 'inf' }; }
    else { S.sol = { kind: 'parallel' }; }
    return;
  }
  var x = (S.c - 6) / (2 * S.m + 1);
  S.sol = { kind: 'unique', x: x, y: S.m * x + 3 };
}

function fmtNum(v) {
  if (!isFinite(v)) return '∞';
  var r = Math.round(v * 100) / 100;
  if (Math.abs(r - Math.round(r)) < 1e-9) return String(Math.round(r));
  return String(r);
}

function toFrac(v) {
  if (!isFinite(v)) return null;
  for (var d = 1; d <= 24; d++) {
    var n = Math.round(v * d);
    if (Math.abs(v - n / d) < 1e-9 && (n !== 0 || d === 1)) return [n, d];
  }
  return null;
}

var canvas = document.createElement('canvas');
canvas.style.width = '100%';
canvas.style.height = '100%';
canvas.style.display = 'block';
document.getElementById('container').appendChild(canvas);

function clippedEnds(slope, b, xmin, xmax, ymin, ymax) {
  var cand = [];
  function add(X, Y) {
    if (X >= xmin - 1e-9 && X <= xmax + 1e-9 && Y >= ymin - 1e-9 && Y <= ymax + 1e-9) cand.push([X, Y]);
  }
  add(xmin, slope * xmin + b);
  add(xmax, slope * xmax + b);
  if (Math.abs(slope) > 1e-9) { add((ymin - b) / slope, ymin); add((ymax - b) / slope, ymax); }
  if (cand.length < 2) return null;
  cand.sort(function (a, b2) { return a[0] - b2[0]; });
  return [cand[0], cand[cand.length - 1]];
}

function drawArrow(ctx, tipX, tipY, dx, dy, len, wid, color) {
  var norm = Math.hypot(dx, dy) || 1;
  dx /= norm; dy /= norm;
  var bx = tipX - dx * len, by = tipY - dy * len;
  var px = -dy, py = dx;
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(tipX, tipY);
  ctx.lineTo(bx + px * wid, by + py * wid);
  ctx.lineTo(bx - px * wid, by - py * wid);
  ctx.closePath();
  ctx.fill();
}

var deco = {
  id: 'deco',
  beforeDatasetsDraw: function (chart) {
    var area = chart.chartArea, xS = chart.scales.x, yS = chart.scales.y, ctx = chart.ctx;
    if (area.width < 20 || area.height < 20) return;
    ctx.save();
    ctx.strokeStyle = GRID;
    ctx.lineWidth = 1;
    ctx.setLineDash([2, 3]);
    for (var gx = Math.ceil(xS.min); gx <= Math.floor(xS.max); gx++) {
      var px = xS.getPixelForValue(gx);
      ctx.beginPath(); ctx.moveTo(px, area.top); ctx.lineTo(px, area.bottom); ctx.stroke();
    }
    for (var gy = Math.ceil(yS.min); gy <= Math.floor(yS.max); gy++) {
      var py = yS.getPixelForValue(gy);
      ctx.beginPath(); ctx.moveTo(area.left, py); ctx.lineTo(area.right, py); ctx.stroke();
    }
    ctx.restore();
  },
  afterDraw: function (chart) {
    var area = chart.chartArea, xS = chart.scales.x, yS = chart.scales.y, ctx = chart.ctx;
    if (area.width < 20 || area.height < 20) return;
    var mDim = Math.min(area.width, area.height);
    var tickFs = Math.max(6, mDim * 0.028);
    var eqFs = Math.max(6, mDim * 0.034);
    var fracFs = Math.max(6, mDim * 0.03);
    var arrowLen = Math.max(2.5, mDim * 0.022);
    var axisLw = Math.max(1.1, mDim * 0.010);
    var dotR = Math.max(1.5, mDim * 0.012);
    var x0p = xS.getPixelForValue(0), y0p = yS.getPixelForValue(0);
    ctx.save();

    // axes with arrowheads
    ctx.strokeStyle = INK; ctx.lineWidth = axisLw; ctx.setLineDash([]);
    ctx.beginPath(); ctx.moveTo(area.left, y0p); ctx.lineTo(area.right, y0p); ctx.stroke();
    drawArrow(ctx, area.left, y0p, -1, 0, arrowLen, arrowLen * 0.55, INK);
    drawArrow(ctx, area.right, y0p, 1, 0, arrowLen, arrowLen * 0.55, INK);
    ctx.beginPath(); ctx.moveTo(x0p, area.top); ctx.lineTo(x0p, area.bottom); ctx.stroke();
    drawArrow(ctx, x0p, area.top, 0, -1, arrowLen, arrowLen * 0.55, INK);
    drawArrow(ctx, x0p, area.bottom, 0, 1, arrowLen, arrowLen * 0.55, INK);

    // tick marks + labels
    var tickL = Math.max(2, mDim * 0.012);
    ctx.font = tickFs + 'px sans-serif';
    ctx.fillStyle = INK;
    for (var gx = Math.ceil(xS.min); gx <= Math.floor(xS.max); gx++) {
      if (gx === 0) continue;
      var px = xS.getPixelForValue(gx);
      ctx.beginPath(); ctx.moveTo(px, y0p - tickL); ctx.lineTo(px, y0p + tickL); ctx.stroke();
      ctx.textAlign = 'center'; ctx.textBaseline = 'top';
      ctx.fillText(String(gx), px, y0p + tickL + 1);
    }
    for (var gy = Math.ceil(yS.min); gy <= Math.floor(yS.max); gy++) {
      if (gy === 0) continue;
      var py = yS.getPixelForValue(gy);
      ctx.beginPath(); ctx.moveTo(x0p - tickL, py); ctx.lineTo(x0p + tickL, py); ctx.stroke();
      ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
      ctx.fillText(String(gy), x0p - tickL - 1.5, py);
    }

    // italic axis labels
    ctx.font = 'italic ' + (tickFs * 1.2) + 'px Georgia, serif';
    ctx.fillStyle = INK;
    ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic';
    ctx.fillText('x', area.right - arrowLen - tickFs * 0.4, y0p - arrowLen - 1);
    ctx.textAlign = 'left';
    ctx.fillText('y', x0p + arrowLen + 1, area.top + tickFs * 1.1);

    // data-line arrowheads at chart boundary
    var lines = [
      { slope: -0.5, b: S.c / 2, color: BLUE },
      { slope: S.m, b: 3, color: RED }
    ];
    for (var li = 0; li < lines.length; li++) {
      var L = lines[li];
      var ends = clippedEnds(L.slope, L.b, xS.min, xS.max, yS.min, yS.max);
      if (!ends) continue;
      var d1x = xS.getPixelForValue(1) - xS.getPixelForValue(0);
      var d1y = yS.getPixelForValue(L.slope * 1 + L.b) - yS.getPixelForValue(L.b);
      var nrm = Math.hypot(d1x, d1y) || 1; d1x /= nrm; d1y /= nrm;
      for (var ei = 0; ei < ends.length; ei++) {
        var px = xS.getPixelForValue(ends[ei][0]);
        var py = yS.getPixelForValue(ends[ei][1]);
        var sgn = (ei === 0) ? -1 : 1;
        drawArrow(ctx, px, py, sgn * d1x, sgn * d1y, arrowLen * 0.9, arrowLen * 0.5, L.color);
      }
    }

    // equation labels in the left margin, anchored to each line
    ctx.font = 'italic ' + eqFs + 'px Georgia, serif';
    var yBlueW = -0.5 * xS.min + S.c / 2;
    var yRedW = S.m * xS.min + 3;
    var blueY = Math.max(area.top + eqFs, Math.min(area.bottom - eqFs * 0.3, yS.getPixelForValue(Math.max(yS.min, Math.min(yS.max, yBlueW)))));
    var redY = Math.max(area.top + eqFs, Math.min(area.bottom - eqFs * 0.3, yS.getPixelForValue(Math.max(yS.min, Math.min(yS.max, yRedW)))));
    if (Math.abs(blueY - redY) < eqFs * 1.3) { blueY -= eqFs * 0.7; redY += eqFs * 0.7; }
    var blueTxt = S.c < 0 ? 'x + 2y = −' + fmtNum(-S.c) : 'x + 2y = ' + fmtNum(S.c);
    var redTxt = Math.abs(S.m - 1) < 1e-9 ? '−x + y = 3' : 'y = ' + fmtNum(S.m) + 'x + 3';
    ctx.textAlign = 'right'; ctx.textBaseline = 'alphabetic';
    ctx.fillStyle = BLUE; ctx.fillText(blueTxt, area.left - 5, blueY);
    ctx.fillStyle = RED; ctx.fillText(redTxt, area.left - 5, redY);

    // solution dot / annotations
    var sol = S.sol;
    if (sol.kind === 'unique' && sol.x >= xS.min && sol.x <= xS.max && sol.y >= yS.min && sol.y <= yS.max) {
      var dpx = xS.getPixelForValue(sol.x), dpy = yS.getPixelForValue(sol.y);
      ctx.fillStyle = '#000';
      ctx.beginPath(); ctx.arc(dpx, dpy, dotR, 0, Math.PI * 2); ctx.fill();
      drawCoordLabel(ctx, sol.x, sol.y, dpx, dpy - dotR - fracFs * 0.5, area, fracFs, dotR, dpy, yS);
    } else {
      var msg, wx = (xS.min + xS.max) / 2 - 3, wy = 1.4;
      if (sol.kind === 'parallel') msg = 'parallel lines — no solution';
      else if (sol.kind === 'inf') msg = 'same line — infinitely many solutions';
      else msg = 'solution is outside the grid';
      if (sol.kind === 'unique') {
        wx = Math.max(xS.min + 0.3, Math.min(xS.max - 0.3, sol.x));
        wy = Math.max(yS.min + 0.5, Math.min(yS.max - 0.5, sol.y));
      }
      var mx = xS.getPixelForValue(wx), my = yS.getPixelForValue(wy);
      ctx.font = fracFs + 'px sans-serif';
      var tw = ctx.measureText(msg).width;
      ctx.fillStyle = 'rgba(255,255,255,0.85)';
      ctx.fillRect(mx - 2, my - fracFs * 1.2, tw + 4, fracFs * 1.7);
      ctx.fillStyle = '#555'; ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
      ctx.fillText(msg, mx, my);
    }
    ctx.restore();
  }
};

function drawCoordLabel(ctx, xv, yv, cx, baseY, area, fs, dotR, dotPy, yS) {
  function atom(v) {
    var f = toFrac(v);
    if (!f) return { t: 'text', s: fmtNum(v) };
    if (f[1] === 1) return { t: 'text', s: String(f[0]) };
    return { t: 'frac', n: String(f[0]), d: String(f[1]) };
  }
  var atoms = [{ t: 'text', s: '(' }, atom(xv), { t: 'text', s: ', ' }, atom(yv), { t: 'text', s: ')' }];
  var small = fs * 0.8, gap = fs * 0.12, w = 0, widths = [], i;
  for (i = 0; i < atoms.length; i++) {
    var a = atoms[i];
    if (a.t === 'text') { ctx.font = fs + 'px sans-serif'; }
    else {
      ctx.font = small + 'px sans-serif';
      a.w = Math.max(ctx.measureText(a.n).width, ctx.measureText(a.d).width) + fs * 0.18;
    }
    if (a.t === 'text') a.w = ctx.measureText(a.s).width;
    widths.push(a.w); w += a.w; if (i > 0) w += gap;
  }
  var x = Math.max(area.left + 2, Math.min(area.right - w - 2, cx - w / 2));
  if (x + w > area.right) x = area.right - w - 2;
  var top = baseY - fs * 1.35;
  if (top < area.top + 1) { top = area.top + 1; baseY = top + fs * 1.35; }
  ctx.fillStyle = 'rgba(255,255,255,0.88)';
  ctx.fillRect(x - 2, top - 1.5, w + 4, fs * 2.1);
  ctx.fillStyle = '#000';
  ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  for (i = 0; i < atoms.length; i++) {
    var at = atoms[i];
    if (at.t === 'text') {
      ctx.font = fs + 'px sans-serif';
      ctx.fillText(at.s, x, baseY);
    } else {
      var xc = x + at.w / 2;
      ctx.font = small + 'px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(at.n, xc, baseY - fs * 0.55);
      ctx.fillText(at.d, xc, baseY + small * 0.9);
      ctx.textAlign = 'left';
      ctx.strokeStyle = '#000'; ctx.lineWidth = Math.max(0.6, fs * 0.06);
      ctx.beginPath(); ctx.moveTo(x, baseY - fs * 0.35); ctx.lineTo(x + at.w, baseY - fs * 0.35); ctx.stroke();
    }
    x += at.w + gap;
  }
}

