});
window.__markRendered();

function drawData() {
  computeSolution();
  chart.data.datasets[0].data = [{ x: -30, y: (S.c + 30) / 2 }, { x: 30, y: (S.c - 30) / 2 }];
  chart.data.datasets[1].data = [{ x: -30, y: S.m * -30 + 3 }, { x: 30, y: S.m * 30 + 3 }];
  chart.update();
}

function renderReadout() {
  var el = document.getElementById('readout');
  if (!el) return;
  var s = S.sol;
  if (s.kind === 'unique') {
    var lhsB = s.x + 2 * s.y;
    var rhsR = S.m * s.x + 3;
    el.textContent = 'solution: (' + fmtNum(s.x) + ', ' + fmtNum(s.y) + ')\nblue: x + 2y = ' + fmtNum(lhsB) + ' ✓ (c = ' + fmtNum(S.c) + ')\nred: mx + 3 = ' + fmtNum(rhsR) + ' = y ✓';
  } else if (s.kind === 'parallel') {
    el.textContent = 'no solution — the lines are parallel';
  } else {
    el.textContent = 'same line — infinitely many solutions';
  }
}

function update_blueIntercept(v) { S.c = v; drawData(); renderReadout(); }
function update_redSlope(v) { S.m = v; drawData(); renderReadout(); }

function trigger_inspectIntersection() {
  var s = S.sol;
  if (s.kind === 'unique') {
    var lhsB = s.x + 2 * s.y, rhsR = S.m * s.x + 3;
    showPopup('One pair satisfies both equations',
      'Substituting (' + fmtNum(s.x) + ', ' + fmtNum(s.y) + '): the blue equation gives x + 2y = ' +
      fmtNum(lhsB) + ', matching c = ' + fmtNum(S.c) + ' ✓, and the red equation gives ' + fmtNum(S.m) +
      '·x + 3 = ' + fmtNum(rhsR) + ' = y ✓. The same ordered pair makes both equations true at once — ' +
      'which is exactly why the crossing point is the system\'s solution.');
  } else if (s.kind === 'parallel') {
    showPopup('No solution',
      'Both lines now have slope −1/2 but different intercepts, so they never meet. No ordered pair can satisfy both equations at the same time, so this system has no solution.');
  } else {
    showPopup('Infinitely many solutions',
      'The two equations now describe the same line, so every point on it satisfies both equations. The system has infinitely many solutions.');
  }
}

function dotHit(e) {
  var s = S.sol;
  if (!s || s.kind !== 'unique') return false;
  if (s.x < chart.scales.x.min || s.x > chart.scales.x.max || s.y < chart.scales.y.min || s.y > chart.scales.y.max) return false;
  var rect = canvas.getBoundingClientRect();
  var px = e.clientX - rect.left, py = e.clientY - rect.top;
  var dpx = chart.scales.x.getPixelForValue(s.x), dpy = chart.scales.y.getPixelForValue(s.y);
  return Math.hypot(px - dpx, py - dpy) <= 10;
}

canvas.addEventListener('click', function (e) { if (dotHit(e)) trigger_inspectIntersection(); });
canvas.addEventListener('mousemove', function (e) {
  if (dotHit(e)) {
    canvas.style.cursor = 'pointer';
    showTooltip('Solution: (' + fmtNum(S.sol.x) + ', ' + fmtNum(S.sol.y) + ') — click to verify in both equations', e);
  } else {
    canvas.style.cursor = 'default';
    hideTooltip();
  }
});
canvas.addEventListener('mouseleave', hideTooltip);

